#| check: true
if result is not None and abs(result - 22670.59) &lt; 0.01:
    feedback = {"correct": True, "message": "Right: about $22,700, from $7,200 put in."}
else:
    feedback = {"correct": False, "message": "Not quite. Check the 12 and the exponent."}
feedback




